package vn.svframe.svframelib.api.crafting.recipes.vmp;
import vn.svframe.svframelib.api.crafting.ingredients.*; import vn.svframe.svframelib.api.crafting.recipes.MythicRecipeStation; import net.minecraft.inventory.Inventory; import net.minecraft.item.ItemStack; import java.util.*; import java.util.concurrent.CopyOnWriteArrayList;
public abstract class VanillaInventoryMapping { private static final List<VanillaInventoryMapping> CUSTOM=new CopyOnWriteArrayList<>(); public abstract int getMainWidth(int row); public abstract int getMainHeight(int col); public abstract int getMainSlot(int x,int y); public abstract int getMainInventoryStart(); public int getMainInventorySize(){return getMainInventoryWidth()*getMainInventoryHeight();} public abstract int getMainInventoryWidth(); public abstract int getMainInventoryHeight(); public MythicRecipeInventory getMainMythicInventory(Inventory inv){return extract(inv,false,null);} public abstract int getResultWidth(int row); public abstract int getResultHeight(int col); public abstract int getResultSlot(int x,int y); public int getResultInventorySize(){return getResultInventoryWidth()*getResultInventoryHeight();} public abstract int getResultInventoryStart(); public abstract int getResultInventoryWidth(); public abstract int getResultInventoryHeight(); public MythicRecipeInventory getResultMythicInventory(Inventory inv){MythicRecipeInventory out=new MythicRecipeInventory();for(int y=0;y<getResultInventoryHeight();y++)for(int x=0;x<getResultInventoryWidth();x++)out.setItemAt(x,y,get(inv,getResultSlot(x,y)));return out;} public abstract int getSideWidth(String name,int row); public abstract int getSideHeight(String name,int col); public abstract int getSideSlot(String name,int x,int y); public abstract int getSideInventoryStart(String name); public int getSideInventorySize(String name){return getSideInventoryWidth(name)*getSideInventoryHeight(name);} public abstract int getSideInventoryWidth(String name); public abstract int getSideInventoryHeight(String name); public MythicRecipeInventory getSideMythicInventory(String name,Inventory inv){validateSide(name);MythicRecipeInventory out=new MythicRecipeInventory();for(int y=0;y<getSideInventoryHeight(name);y++)for(int x=0;x<getSideInventoryWidth(name);x++)out.setItemAt(x,y,get(inv,getSideSlot(name,x,y)));return out;} public abstract ArrayList<String> getSideInventoryNames(); public HashMap<String,MythicRecipeInventory> getSideMythicInventories(Inventory inv){HashMap<String,MythicRecipeInventory> out=new HashMap<>();for(String n:getSideInventoryNames())out.put(n,getSideMythicInventory(n,inv));return out;} public void validateSide(String n){if(!getSideInventoryNames().contains(n))throw sideInventoryException(n);} public IllegalArgumentException sideInventoryException(String n){return new IllegalArgumentException("Unknown side inventory: "+n);} public void applyToMainInventory(Inventory inv,MythicRecipeInventory src,boolean clear){apply(inv,src,false,null,clear);} public void applyToResultInventory(Inventory inv,MythicRecipeInventory src,boolean clear){if(clear)for(int i=0;i<getResultInventorySize();i++)inv.setStack(getResultInventoryStart()+i,ItemStack.EMPTY);for(int y=0;y<src.getHeight();y++)for(int x=0;x<src.getWidth();x++)inv.setStack(getResultSlot(x,y),src.getItemAt(x,y).copy());inv.markDirty();} public boolean applyToSideInventory(Inventory inv,MythicRecipeInventory src,String side,boolean clear){validateSide(side);if(clear)for(int y=0;y<getSideInventoryHeight(side);y++)for(int x=0;x<getSideInventoryWidth(side);x++)inv.setStack(getSideSlot(side,x,y),ItemStack.EMPTY);for(int y=0;y<src.getHeight();y++)for(int x=0;x<src.getWidth();x++)inv.setStack(getSideSlot(side,x,y),src.getItemAt(x,y).copy());inv.markDirty();return true;} public MythicBlueprintInventory extractFrom(Inventory inv){MythicBlueprintInventory b=new MythicBlueprintInventory(getMainMythicInventory(inv),getResultMythicInventory(inv));for(String n:getSideInventoryNames())b.addSideInventory(n,getSideMythicInventory(n,inv));return b;} public abstract boolean isResultSlot(int raw); public abstract boolean mainIsResult(); public abstract String getIntendedInventory(); public abstract MythicRecipeStation getIntendedStation(); public static void setInventoryItemAmount(Inventory inv,int slot,ItemStack stack){setInventoryItem(inv,slot,stack);} public static void setInventoryItem(Inventory inv,int slot,ItemStack stack){inv.setStack(slot,stack==null?ItemStack.EMPTY:stack.copy());inv.markDirty();} public static void setInventoryItem(Inventory inv,int slot,ItemStack stack,boolean ignored){setInventoryItem(inv,slot,stack);} public static ItemStack get(Inventory inv,int slot){return slot<0||slot>=inv.size()?ItemStack.EMPTY:inv.getStack(slot);} public void throwOutOfBounds(int i){throw outOfBounds(i);} public IllegalArgumentException outOfBounds(int i){return new IllegalArgumentException("Out of bounds: "+i);} public void throwOutOfBounds(int x,int y){throw outOfBounds(x,y);} public IllegalArgumentException outOfBounds(int x,int y){return new IllegalArgumentException("Out of bounds: "+x+","+y);} public static void registerAll(){registerCustomMapping(new SuperWorkbenchMapping());registerCustomMapping(new MegaWorkbenchMapping());} public static void registerCustomMapping(VanillaInventoryMapping m){if(CUSTOM.stream().noneMatch(x->x.getClass()==m.getClass()))CUSTOM.add(m);} public static List<VanillaInventoryMapping> getCustomMappings(){return List.copyOf(CUSTOM);} private MythicRecipeInventory extract(Inventory inv,boolean side,String n){MythicRecipeInventory out=new MythicRecipeInventory();for(int y=0;y<getMainInventoryHeight();y++)for(int x=0;x<getMainInventoryWidth();x++)out.setItemAt(x,y,get(inv,getMainSlot(x,y)));return out;} private void apply(Inventory inv,MythicRecipeInventory src,boolean side,String n,boolean clear){if(clear)for(int y=0;y<getMainInventoryHeight();y++)for(int x=0;x<getMainInventoryWidth();x++)inv.setStack(getMainSlot(x,y),ItemStack.EMPTY);for(int y=0;y<src.getHeight();y++)for(int x=0;x<src.getWidth();x++)inv.setStack(getMainSlot(x,y),src.getItemAt(x,y).copy());inv.markDirty();} }
